class StgError(Exception):
    def __init__(self, message: str, exit_code: int = 2):
        super().__init__(message)
        self.message = message
        self.exit_code = exit_code


@dataclass
class Repo:
    toplevel: Path
    git_dir: Path
    branch: str
    branch_ref: str
    head: str


@dataclass
class Patch:
    name: str
    commit: str


@dataclass
class StackState:
    branch: str
    base: str
    applied: int
    patches: List[Patch]


def eprint(text: str) -> None:
    print(text, file=sys.stderr)


def print_help(text: str) -> int:
    print(text)
    return 0


def parser_error(message: str, usage_key: str) -> int:
    usage = USAGE_BY_COMMAND[usage_key]
    eprint(f"error: {message}\n")
    eprint(f"Usage: {usage}\n")
    eprint("For more information, try '--help'.")
    return 1


def fatal(message: str, exit_code: int = 2) -> int:
    eprint(f"error: {message}")
    return exit_code


def run(
    args: List[str],
    *,
    capture: bool = True,
    check: bool = True,
    input_text: Optional[str] = None,
    env: Optional[dict[str, str]] = None,
) -> subprocess.CompletedProcess[str]:
    result = subprocess.run(
        args,
        text=True,
        input=input_text,
        capture_output=capture,
        env=env,
    )
    if check and result.returncode != 0:
        raise subprocess.CalledProcessError(
            result.returncode,
            args,
            output=result.stdout,
            stderr=result.stderr,
        )
    return result


def git(
    *git_args: str,
    capture: bool = True,
    check: bool = True,
    input_text: Optional[str] = None,
    env: Optional[dict[str, str]] = None,
) -> subprocess.CompletedProcess[str]:
    return run(["git", *git_args], capture=capture, check=check, input_text=input_text, env=env)


def ensure_repo(require_head: bool = True) -> Repo:
    try:
        toplevel = git("rev-parse", "--show-toplevel").stdout.strip()
        git_dir = git("rev-parse", "--git-dir").stdout.strip()
    except subprocess.CalledProcessError as err:
        stderr = (err.stderr or "").strip()
        if "not a git repository" in stderr:
            raise StgError("Could not find a git repository in '.' or in any of its parents")
        raise StgError("Could not find a git repository in '.' or in any of its parents")

    branch_proc = git("symbolic-ref", "--quiet", "--short", "HEAD", check=False)
    branch_ref_proc = git("symbolic-ref", "--quiet", "HEAD", check=False)
    branch = branch_proc.stdout.strip()
    branch_ref = branch_ref_proc.stdout.strip()
    if not branch or not branch_ref:
        raise StgError("HEAD is detached")

    head_proc = git("rev-parse", "HEAD", check=False)
    head = head_proc.stdout.strip()
    if require_head and head_proc.returncode != 0:
        raise StgError(f"branch `{branch_ref}` is unborn")
    return Repo(Path(toplevel), Path(git_dir), branch, branch_ref, head)


def branch_ref_to_commit(branch: str) -> str:
    proc = git("rev-parse", f"refs/heads/{branch}", check=False)
    if proc.returncode != 0:
        raise StgError(f"branch `{branch}` not found")
    return proc.stdout.strip()


def state_file(repo: Repo, branch: str) -> Path:
    encoded = branch.replace("/", "%2F")
    return repo.git_dir / "stg" / f"{encoded}.json"


def load_state(repo: Repo, branch: Optional[str] = None, create_empty_if_missing: bool = True) -> StackState:
    branch_name = branch or repo.branch
    path = state_file(repo, branch_name)
    if path.exists():
        data = json.loads(path.read_text())
        return StackState(
            branch=data["branch"],
            base=data["base"],
            applied=data["applied"],
            patches=[Patch(name=item["name"], commit=item["commit"]) for item in data["patches"]],
        )
    if create_empty_if_missing:
        base = branch_ref_to_commit(branch_name) if branch_name != repo.branch else repo.head
        return StackState(branch=branch_name, base=base, applied=0, patches=[])
    raise StgError(f"StGit stack already initialized for branch `{branch_name}`")


def save_state(repo: Repo, state: StackState) -> None:
    path = state_file(repo, state.branch)
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "branch": state.branch,
        "base": state.base,
        "applied": state.applied,
        "patches": [{"name": patch.name, "commit": patch.commit} for patch in state.patches],
    }
    tmp_fd, tmp_name = tempfile.mkstemp(prefix=".stgstate.", dir=path.parent)
    os.close(tmp_fd)
    Path(tmp_name).write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n")
    os.replace(tmp_name, path)
    current = state.base if state.applied == 0 else state.patches[state.applied - 1].commit
    git("update-ref", f"refs/stacks/{state.branch}", current, capture=True)
    existing_refs = git("for-each-ref", "--format=%(refname)", f"refs/patches/{state.branch}", capture=True).stdout.splitlines()
    keep_refs = {f"refs/patches/{state.branch}/{patch.name}" for patch in state.patches}
    for ref in existing_refs:
        if ref and ref not in keep_refs:
            git("update-ref", "-d", ref, capture=True, check=False)
    for patch in state.patches:
        git("update-ref", f"refs/patches/{state.branch}/{patch.name}", patch.commit, capture=True)


def init_state(repo: Repo, branch: Optional[str] = None) -> StackState:
    target_branch = branch or repo.branch
    existing = state_file(repo, target_branch)
    if existing.exists():
        raise StgError(f"StGit stack already initialized for branch `{target_branch}`")
    base = branch_ref_to_commit(target_branch) if target_branch != repo.branch else repo.head
    state = StackState(branch=target_branch, base=base, applied=0, patches=[])
    save_state(repo, state)
    return state


def current_commit_message(commit: str) -> str:
    return git("log", "-1", "--format=%B", commit).stdout


def commit_parent(commit: str) -> str:
    line = git("rev-list", "--parents", "-n", "1", commit).stdout.strip().split()
    return line[1] if len(line) > 1 else ""


def create_commit(tree: str, parent: str, message: str) -> str:
    proc = git("commit-tree", tree, "-p", parent, capture=True, input_text=message)
    return proc.stdout.strip()


def working_tree_for_refresh(use_index: bool) -> str:
    if use_index:
        return git("write-tree").stdout.strip()
    repo = ensure_repo()
    actual_index = repo.git_dir / "index"
    with tempfile.NamedTemporaryFile(prefix="stg-index.", delete=False) as handle:
        temp_index = handle.name
    try:
        Path(temp_index).write_bytes(actual_index.read_bytes() if actual_index.exists() else b"")
        env = os.environ.copy()
        env["GIT_INDEX_FILE"] = temp_index
        git("add", "-A", capture=True, env=env)
        return git("write-tree", capture=True, env=env).stdout.strip()
    finally:
        try:
            os.unlink(temp_index)
        except FileNotFoundError:
            pass


def has_staged_changes() -> bool:
    return git("diff", "--cached", "--quiet", check=False, capture=True).returncode != 0


def has_unstaged_changes() -> bool:
    return git("diff", "--quiet", check=False, capture=True).returncode != 0


def check_refresh_index(force: bool, use_index: bool) -> None:
    if force or use_index:
        return
    if has_staged_changes() and has_unstaged_changes():
        raise StgError("the index is dirty; consider using `--index` or `--force`")


def patch_index(state: StackState, name: str) -> int:
    for idx, patch in enumerate(state.patches):
        if patch.name == name:
            return idx
    raise StgError(f"patch `{name}` does not exist")


def slugify(value: str) -> str:
    first = value.strip().splitlines()[0] if value.strip() else ""
    slug = re.sub(r"[^a-z0-9]+", "-", first.lower()).strip("-")
    return slug or "patch"


def unique_patch_name(state: StackState, requested: Optional[str], message: str) -> str:
    names = {patch.name for patch in state.patches}
    if requested:
        if requested in names:
            raise StgError(f"patch `{requested}` already exists")
        return requested
    base = slugify(message)
    candidate = base
    suffix = 1
    while candidate in names:
        candidate = f"{base}-{suffix}"
        suffix += 1
    return candidate


def selected_patches_for_series(state: StackState, *, applied_only: bool, unapplied_only: bool, hidden_only: bool) -> List[tuple[str, Patch]]:
    if hidden_only:
        return []
    selected: List[tuple[str, Patch]] = []
    for idx, patch in enumerate(state.patches):
        if idx < state.applied:
            if unapplied_only:
                continue
            prefix = ">" if idx == state.applied - 1 else "+"
        else:
            if applied_only:
                continue
            prefix = "-"
        selected.append((prefix, patch))
    return selected


def hard_reset(commit: str) -> None:
    git("reset", "--hard", "-q", commit, capture=True)


def rebuild_applied(repo: Repo, state: StackState, target_applied: int) -> None:
    hard_reset(state.base)
    current = state.base
    for idx in range(target_applied):
        patch = state.patches[idx]
        if commit_parent(patch.commit) == current:
            hard_reset(patch.commit)
            current = patch.commit
            continue
        pick = git(
            "cherry-pick",
            "--allow-empty",
            "--keep-redundant-commits",
            "-q",
            patch.commit,
            check=False,
            capture=True,
        )
        if pick.returncode != 0:
            git("cherry-pick", "--abort", capture=True, check=False)
            stderr = (pick.stderr or "").strip()
            raise StgError(stderr or "could not apply patch")
        patch.commit = git("rev-parse", "HEAD").stdout.strip()
        current = patch.commit
    state.applied = target_applied
    save_state(repo, state)


def read_message(args: List[str], index: int) -> tuple[str, int]:
    if index >= len(args):
        return "", index
    return args[index], index + 1


def command_init(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["init"])
    branch = None
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-b", "--branch"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--branch <branch>' but none was supplied", "init")
            branch = args[idx]
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "init")
        else:
            return parser_error(f"unexpected argument '{arg}' found", "init")
        idx += 1
    try:
        repo = ensure_repo()
        init_state(repo, branch)
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def refresh_patch_commit(
    repo: Repo,
    state: StackState,
    patch_idx: int,
    *,
    use_index: bool,
    force: bool,
    message: Optional[str],
    show_temp_output: bool,
) -> int:
    if state.applied == 0:
        raise StgError("no patches applied")
    if patch_idx != state.applied - 1:
        raise StgError("only refreshing the top patch is supported")
    check_refresh_index(force, use_index)
    patch = state.patches[patch_idx]
    old_message = current_commit_message(patch.commit)
    parent = state.base if patch_idx == 0 else state.patches[patch_idx - 1].commit
    tree = working_tree_for_refresh(use_index)
    new_message = message if message is not None else old_message
    old_tree = git("show", f"{patch.commit}^{{tree}}").stdout.strip()
    changed = (tree != old_tree) or (new_message != old_message)
    if changed:
        patch.commit = create_commit(tree, parent, new_message)
    hard_reset(patch.commit)
    save_state(repo, state)
    if show_temp_output:
        print("> refresh-temp (new)")
        print("- refresh-temp")
        print("# refresh-temp")
        if changed:
            print(f"& {patch.name}")
        print(f"> {patch.name}")
    return 0


def command_new(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["new"])
    name_arg: Optional[str] = None
    explicit_name: Optional[str] = None
    message: Optional[str] = None
    message_file: Optional[str] = None
    refresh = False
    use_index = False
    force = False
    idx = 0
    paths_mode = False
    while idx < len(args):
        arg = args[idx]
        if paths_mode:
            refresh = True
            idx += 1
            continue
        if arg == "--":
            paths_mode = True
        elif arg in ("-n", "--name"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--name <name>' but none was supplied", "new")
            explicit_name = args[idx]
        elif arg in ("-m", "--message"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--message <message>' but none was supplied", "new")
            message = args[idx]
        elif arg in ("-f", "--file"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--file <path>' but none was supplied", "new")
            message_file = args[idx]
        elif arg in ("-r", "--refresh"):
            refresh = True
        elif arg in ("-i", "--index"):
            use_index = True
            refresh = True
        elif arg in ("-F", "--force"):
            force = True
        elif arg in ("-e", "--edit", "-d", "--diff", "--no-verify", "--submodules", "--no-submodules", "--committer-date-is-author-date"):
            pass
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "new")
        elif arg.startswith("--save-template") or arg.startswith("--author") or arg.startswith("--authname") or arg.startswith("--authemail") or arg.startswith("--authdate"):
            if "=" not in arg:
                idx += 1
                if idx >= len(args):
                    return parser_error(f"a value is required for '{arg}' but none was supplied", "new")
        elif arg.startswith("--ack") or arg.startswith("--review") or arg.startswith("-s") or arg.startswith("--signoff"):
            pass
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "new")
        elif name_arg is None:
            name_arg = arg
        else:
            refresh = True
        idx += 1

    if message_file:
        if message_file == "-":
            message = sys.stdin.read()
        else:
            message = Path(message_file).read_text()
    message = message if message is not None else (name_arg or explicit_name or "patch")
    try:
        repo = ensure_repo()
        state = load_state(repo, create_empty_if_missing=True)
        if not state_file(repo, state.branch).exists():
            state = init_state(repo)
        name = unique_patch_name(state, explicit_name or name_arg, message)
        parent = state.base if state.applied == 0 else state.patches[state.applied - 1].commit
        tree = working_tree_for_refresh(use_index) if refresh else git("show", f"{parent}^{{tree}}").stdout.strip()
        commit = create_commit(tree, parent, message)
        state.patches.insert(state.applied, Patch(name=name, commit=commit))
        state.applied += 1
        if refresh:
            hard_reset(commit)
        else:
            git("update-ref", f"refs/heads/{repo.branch}", commit, capture=True)
        save_state(repo, state)
        print(f"> {name} (new)")
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_refresh(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["refresh"])
    use_index = False
    force = False
    message: Optional[str] = None
    message_file: Optional[str] = None
    patch_name: Optional[str] = None
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-i", "--index"):
            use_index = True
        elif arg in ("-F", "--force"):
            force = True
        elif arg in ("-m", "--message"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--message <message>' but none was supplied", "refresh")
            message = args[idx]
        elif arg in ("-f", "--file"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--file <path>' but none was supplied", "refresh")
            message_file = args[idx]
        elif arg in ("-p", "--patch"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--patch <patch>' but none was supplied", "refresh")
            patch_name = args[idx]
        elif arg in ("-u", "--update", "-e", "--edit", "-d", "--diff", "--no-verify", "--submodules", "--no-submodules"):
            pass
        elif arg.startswith("--conflicts"):
            pass
        elif arg in ("-a", "--annotate"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--annotate <note>' but none was supplied", "refresh")
        elif arg.startswith("--author") or arg.startswith("--authname") or arg.startswith("--authemail") or arg.startswith("--authdate"):
            if "=" not in arg:
                idx += 1
                if idx >= len(args):
                    return parser_error(f"a value is required for '{arg}' but none was supplied", "refresh")
        elif arg.startswith("--ack") or arg.startswith("--review") or arg.startswith("-s") or arg.startswith("--signoff") or arg == "--committer-date-is-author-date":
            pass
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "refresh")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "refresh")
        idx += 1
    if message_file:
        if message_file == "-":
            message = sys.stdin.read()
        else:
            message = Path(message_file).read_text()
    try:
        repo = ensure_repo()
        state = load_state(repo)
        patch_idx = patch_index(state, patch_name) if patch_name else state.applied - 1
        return refresh_patch_commit(repo, state, patch_idx, use_index=use_index, force=force, message=message, show_temp_output=True)
    except StgError as err:
        return fatal(err.message, err.exit_code)


