    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["series"])
    branch = None
    applied_only = False
    unapplied_only = False
    hidden_only = False
    count_only = False
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-b", "--branch"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--branch <branch>' but none was supplied", "series")
            branch = args[idx]
        elif arg in ("-A", "--applied"):
            applied_only = True
        elif arg in ("-U", "--unapplied"):
            unapplied_only = True
        elif arg in ("-H", "--hidden"):
            hidden_only = True
        elif arg in ("-a", "--all"):
            pass
        elif arg in ("-c", "--count"):
            count_only = True
        elif arg in ("-s", "--short", "--author", "-d", "--description", "-e", "--empty", "-P", "--no-prefix", "-I", "--indices", "-O", "--offsets", "-r", "--reverse", "--showbranch"):
            if arg == "-s" and idx + 1 < len(args) and not args[idx + 1].startswith("-"):
                idx += 1
        elif arg == "-m" or arg == "--missing":
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--missing <branch>' but none was supplied", "series")
        elif arg.startswith("--commit-id"):
            pass
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "series")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "series")
        idx += 1
    try:
        repo = ensure_repo()
        state = load_state(repo, branch=branch)
        selected = selected_patches_for_series(state, applied_only=applied_only, unapplied_only=unapplied_only, hidden_only=hidden_only)
        if count_only:
            print(len(selected))
            return 0
        for prefix, patch in selected:
            print(f"{prefix} {patch.name}")
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_top_like(command: str, args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND[command])
    branch = None
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-b", "--branch"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--branch <branch>' but none was supplied", command)
            branch = args[idx]
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", command)
        else:
            return parser_error(f"unexpected argument '{arg}' found", command)
        idx += 1
    try:
        repo = ensure_repo()
        state = load_state(repo, branch=branch)
        if command == "top":
            if state.applied == 0:
                raise StgError("no patches applied")
            print(state.patches[state.applied - 1].name)
        elif command == "prev":
            if state.applied == 0:
                raise StgError("no patches applied")
            if state.applied < 2:
                raise StgError("not enough patches applied")
            print(state.patches[state.applied - 2].name)
        elif command == "next":
            if state.applied >= len(state.patches):
                raise StgError("no unapplied patches")
            print(state.patches[state.applied].name)
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def selection_target_for_count(total: int, applied: int, number: int, *, push: bool) -> int:
    if push:
        if number >= 0:
            return min(total, applied + number)
        return max(applied, total + number)
    if number >= 0:
        return max(0, applied - number)
    return min(total, -number)


def print_pop_like(state: StackState, old_applied: int) -> None:
    for idx in range(old_applied - 1, state.applied - 1, -1):
        print(f"- {state.patches[idx].name}")
    if state.applied > 0:
        print(f"> {state.patches[state.applied - 1].name}")


def print_push_like(state: StackState, old_applied: int) -> None:
    for idx in range(old_applied, state.applied):
        prefix = ">" if idx == state.applied - 1 else "+"
        print(f"{prefix} {state.patches[idx].name}")


def command_pop(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["pop"])
    pop_all = False
    number: Optional[int] = None
    names: List[str] = []
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-a", "--all"):
            pop_all = True
        elif arg in ("-n", "--number"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--number <number>' but none was supplied", "pop")
            number = int(args[idx])
        elif arg in ("-s", "--spill", "-k", "--keep"):
            pass
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "pop")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "pop")
        else:
            names.append(arg)
        idx += 1
    try:
        repo = ensure_repo()
        state = load_state(repo)
        if state.applied == 0:
            raise StgError("no patches applied")
        old_applied = state.applied
        if pop_all:
            target = 0
        elif number is not None:
            target = selection_target_for_count(len(state.patches), state.applied, number, push=False)
        elif names:
            target = min(patch_index(state, name) for name in names)
        else:
            target = state.applied - 1
        target = max(0, min(target, state.applied))
        rebuild_applied(repo, state, target)
        print_pop_like(state, old_applied)
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_push(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["push"])
    push_all = False
    number: Optional[int] = None
    names: List[str] = []
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-a", "--all"):
            push_all = True
        elif arg in ("-n", "--number"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--number <n>' but none was supplied", "push")
            number = int(args[idx])
        elif arg in ("-k", "--keep", "-m", "--merged", "--reverse", "--noapply", "--set-tree", "--committer-date-is-author-date"):
            pass
        elif arg.startswith("--conflicts") or arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "push")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "push")
        else:
            names.append(arg)
        idx += 1
    try:
        repo = ensure_repo()
        state = load_state(repo)
        if state.applied >= len(state.patches):
            raise StgError("no unapplied patches")
        old_applied = state.applied
        if push_all:
            target = len(state.patches)
        elif number is not None:
            target = selection_target_for_count(len(state.patches), state.applied, number, push=True)
        elif names:
            target = max(patch_index(state, name) + 1 for name in names)
        else:
            target = state.applied + 1
        target = max(state.applied, min(target, len(state.patches)))
        rebuild_applied(repo, state, target)
        print_push_like(state, old_applied)
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_goto(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["goto"])
    patch_name: Optional[str] = None
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-k", "--keep", "-m", "--merged", "--committer-date-is-author-date"):
            pass
        elif arg.startswith("--conflicts") or arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "goto")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "goto")
        elif patch_name is None:
            patch_name = arg
        else:
            return parser_error(f"unexpected argument '{arg}' found", "goto")
        idx += 1
    if patch_name is None:
        return parser_error("the following required arguments were not provided:\n  <patch>", "goto")
    try:
        repo = ensure_repo()
        state = load_state(repo)
        target = patch_index(state, patch_name) + 1
        old_applied = state.applied
        rebuild_applied(repo, state, target)
        if target < old_applied:
            print_pop_like(state, old_applied)
        elif target > old_applied:
            print_push_like(state, old_applied)
        else:
            print(f"> {patch_name}")
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_delete(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["delete"])
    delete_all = False
    delete_top = False
    names: List[str] = []
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-a", "--all"):
            delete_all = True
        elif arg in ("-t", "--top"):
            delete_top = True
        elif arg in ("-A", "--applied", "-U", "--unapplied", "-H", "--hidden", "--spill"):
            pass
        elif arg in ("-b", "--branch"):
            idx += 1
            if idx >= len(args):
                return parser_error("a value is required for '--branch <branch>' but none was supplied", "delete")
        elif arg.startswith("--conflicts") or arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "delete")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "delete")
        else:
            names.append(arg)
        idx += 1
    try:
        repo = ensure_repo()
        state = load_state(repo)
        if delete_all:
            targets = list(range(len(state.patches)))
        elif delete_top:
            if state.applied == 0:
                raise StgError("no patches applied")
            targets = [state.applied - 1]
        elif names:
            targets = sorted({patch_index(state, name) for name in names})
        else:
            return parser_error("the following required arguments were not provided:\n  [<patch>...]", "delete")
        old_applied = state.applied
        popped: List[str] = []
        deleted: List[str] = []
        for idx in sorted(targets, reverse=True):
            patch = state.patches[idx]
            if idx < state.applied:
                popped.append(patch.name)
                state.applied -= 1
            deleted.append(patch.name)
            del state.patches[idx]
        rebuild_applied(repo, state, state.applied)
        for name in popped:
            print(f"- {name}")
        for name in deleted:
            print(f"# {name}")
        if state.applied > 0:
            print(f"> {state.patches[state.applied - 1].name}")
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_branch(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(HELP_BY_COMMAND["branch"])
    list_mode = False
    create_mode = False
    merge_mode = False
    positionals: List[str] = []
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-l", "--list"):
            list_mode = True
        elif arg in ("-c", "--create"):
            create_mode = True
        elif arg == "--merge":
            merge_mode = True
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "branch")
        elif arg in ("-C", "--clone", "-r", "--rename", "-p", "--protect", "-u", "--unprotect", "-D", "--delete", "--cleanup", "-d", "--describe"):
            return parser_error(f"unexpected argument '{arg}' found", "branch")
        elif arg.startswith("-"):
            return parser_error(f"unexpected argument '{arg}' found", "branch")
        else:
            positionals.append(arg)
        idx += 1
    try:
        repo = ensure_repo()
        if list_mode:
            current = repo.branch
            branches = git("for-each-ref", "--format=%(refname:short)", "refs/heads").stdout.splitlines()
            for branch in branches:
                marker = ">" if branch == current else " "
                print(f"{marker}   \t{branch}  |")
            return 0
        if create_mode:
            if not positionals:
                return parser_error("the following required arguments were not provided:\n  <new-branch>", "branch")
            new_branch = positionals[0]
            committish = positionals[1] if len(positionals) > 1 else None
            cmd = ["branch", new_branch]
            if committish:
                cmd.append(committish)
            branch_result = git(*cmd, capture=True, check=False)
            if branch_result.returncode != 0:
                stderr = (branch_result.stderr or "").strip()
                raise StgError(stderr or f"branch `{new_branch}` not found")
            git("checkout", "-q", new_branch, capture=True)
            repo = ensure_repo()
            init_state(repo)
            eprint("info: Recording as a local branch")
            return 0
        if merge_mode:
            if not positionals:
                return parser_error("the following required arguments were not provided:\n  <branch>", "branch")
        if not positionals:
            print(repo.branch)
            return 0
        target = positionals[0]
        result = git("checkout", "-q", target, capture=True, check=False)
        if result.returncode != 0:
            raise StgError(f"branch `{target}` not found")
        return 0
    except StgError as err:
        return fatal(err.message, err.exit_code)


def command_version(args: List[str]) -> int:
    if "--help" in args or "-h" in args:
        return print_help(VERSION_HELP)
    short = False
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if arg in ("-s", "--short"):
            short = True
        elif arg.startswith("--color"):
            if arg == "--color":
                idx += 1
                if idx >= len(args):
                    return parser_error("a value is required for '--color <when>' but none was supplied", "version")
        else:
            return parser_error(f"unexpected argument '{arg}' found", "version")
        idx += 1
    if short:
        print(f"stg {VERSION}")
        return 0
    git_version = git("--version").stdout.strip()
    print(VERSION_BANNER)
    print(git_version)
    return 0


def command_help(args: List[str]) -> int:
    if not args:
        return print_help(ROOT_HELP_LONG)
    topic = args[0]
    if topic in HELP_BY_COMMAND:
        return print_help(HELP_BY_COMMAND[topic])
    if topic == "help":
        return print_help(ROOT_HELP_LONG)
    print(ROOT_HELP_LONG)
    return fatal(f"unrecognized subcommand '{topic}'", 1)


def command_alias(command: str, args: List[str]) -> int:
    cmd = ["git", ALIAS_GIT_SUBCOMMAND[command], *ALIAS_PREFIX_ARGS.get(command, []), *args]
    completed = subprocess.run(cmd)
    return completed.returncode


def apply_global_options(argv: List[str]) -> tuple[List[str], Optional[int]]:
    args = list(argv)
    out: List[str] = []
    idx = 0
    while idx < len(args):
        arg = args[idx]
        if out:
            out.append(arg)
            idx += 1
            continue
        if arg == "--version":
            return [], command_version([])
        if arg == "--help":
            return [], print_help(ROOT_HELP_LONG)
        if arg == "-h":
            return [], print_help(ROOT_HELP_SHORT)
        if arg == "-C":
            idx += 1
            if idx >= len(args):
                return [], parser_error("a value is required for '-C <path>' but none was supplied", "root")
            target = args[idx]
            if not os.path.isabs(target):
                target = os.path.join(os.getcwd(), target)
            os.chdir(target)
        elif arg.startswith("--color="):
            pass
        elif arg == "--color":
            idx += 1
            if idx >= len(args):
                return [], parser_error("a value is required for '--color <when>' but none was supplied", "root")
        elif arg.startswith("-"):
            return [], parser_error(f"unexpected argument '{arg}' found", "root")
        else:
            out.append(arg)
        idx += 1
    return out, None


def dispatch(command: str, args: List[str]) -> int:
    if command not in KNOWN_COMMANDS:
        return parser_error(f"unrecognized subcommand '{command}'", "root")
    if command not in IMPLEMENTED_COMMANDS:
        if args and args[0] in ("-h", "--help"):
            return print_help(ROOT_HELP_LONG)
        return fatal(f"subcommand `{command}` is not implemented", 1)
    if command == "init":
        return command_init(args)
    if command == "new":
        return command_new(args)
    if command == "refresh":
        return command_refresh(args)
    if command == "series":
        return command_series(args)
    if command in {"top", "prev", "next"}:
        return command_top_like(command, args)
    if command == "pop":
        return command_pop(args)
    if command == "push":
        return command_push(args)
    if command == "goto":
        return command_goto(args)
    if command == "delete":
        return command_delete(args)
    if command == "branch":
        return command_branch(args)
    if command == "version":
        return command_version(args)
    if command == "help":
        return command_help(args)
    if command in ALIAS_GIT_SUBCOMMAND:
        return command_alias(command, args)
    return fatal(f"subcommand `{command}` is not implemented", 1)


def main(argv: Optional[List[str]] = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    args, early = apply_global_options(args)
    if early is not None:
        return early
    if not args:
        print(ROOT_HELP_SHORT)
        return 1
    return dispatch(args[0], args[1:])


if __name__ == "__main__":
    raise SystemExit(main())
